226	    /**
227	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
228	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
229	     */
230	    static LocalDate toBusinessDay(LocalDate date) {
231	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
232	            date = date.plusDays(1);
233	        }
234	        return date;
235	    }
