237	    /**
238	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
239	     * using the same per-day accumulation path as the daily create-limit rule.
240	     */
241	    private long ownersCreatedOn(LocalDate registrationDate) {
242	        LocalDate day = toBusinessDay(registrationDate);
243	        return this.clinicService.findAllOwners().stream()
244	            .map(Owner::getRegistrationDate)
245	            .filter(existing -> existing != null)
246	            .map(OwnerRestControllerV1::toBusinessDay)
247	            .filter(day::equals)
248	            .count();
249	    }
