251	    /** Upper-cased first three characters of {@code value} (fewer if it is shorter); "" when null. */
252	    private static String prefix3(String value) {
253	        String letters = value == null ? "" : value;
254	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase();
255	    }
