285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
288	        String telephone = toE164(ownerFieldsDto.getTelephone());
289	        if (telephone == null) {
290	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
291	        }
292	        String email = ownerFieldsDto.getEmail();
293	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
294	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
295	        }
296	        String address = normaliseAddress(ownerFieldsDto.getAddress());
297	        if (address.isEmpty()) {
298	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
299	        }
300	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
301	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
302	        LocalDate registrationDate = toBusinessDay(effectiveDate);
303	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
304	            .map(Owner::getRegistrationDate)
305	            .filter(existing -> existing != null)
306	            .map(OwnerRestControllerV1::toBusinessDay)
307	            .filter(registrationDate::equals)
308	            .count();
309	        if (ownersCreatedThatDay >= 100) {
310	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
311	        }
312	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
313	        long ownersInCity = this.clinicService.findAllOwners().stream()
314	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
315	            .count();
316	        if (ownersInCity >= 50) {
317	            return new ResponseEntity<>(HttpStatus.CONFLICT);
318	        }
319	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
320	            .map(Owner::getTelephone)
321	            .map(OwnerRestControllerV1::toE164)
322	            .filter(existing -> existing != null)
323	            .anyMatch(telephone::equals);
324	        if (telephoneInUse) {
325	            return new ResponseEntity<>(HttpStatus.CONFLICT);
326	        }
327	        if (email != null) {
328	            String emailKey = email.toLowerCase();
329	            boolean emailInUse = this.clinicService.findAllOwners().stream()
330	                .map(Owner::getEmail)
331	                .filter(existing -> existing != null)
332	                .map(String::toLowerCase)
333	                .anyMatch(emailKey::equals);
334	            if (emailInUse) {
335	                return new ResponseEntity<>(HttpStatus.CONFLICT);
336	            }
337	        }
338	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
339	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
340	        String addressKey = address;
341	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
342	            .filter(existing ->
343	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
344	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
345	            .toList();
346	        if (!householdMembers.isEmpty() && !sharesHousehold) {
347	            return new ResponseEntity<>(HttpStatus.CONFLICT);
348	        }
349	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
350	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
351	            .filter(existing ->
352	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
353	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
354	            .count();
355	        HttpHeaders headers = new HttpHeaders();
356	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
357	        owner.setNamesakeCount(namesakeCount);
358	        owner.setAddress(address);
359	        owner.setTelephone(telephone);
360	        owner.setEmail(email == null ? null : email.toLowerCase());
361	        owner.setRegistrationDate(registrationDate);
362	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
363	        if (sharesHousehold && !householdMembers.isEmpty()) {
364	            String householdId = householdId(lastNameKey, addressKey);
365	            owner.setHouseholdId(householdId);
366	            for (Owner member : householdMembers) {
367	                if (member.getHouseholdId() == null) {
368	                    member.setHouseholdId(householdId);
369	                    this.clinicService.saveOwner(member);
370	                }
371	            }
372	        }
373	        this.clinicService.saveOwner(owner);
374	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
375	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
376	            ownerMapper.formatMembershipLevel(owner));
377	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
378	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
379	        headers.setLocation(UriComponentsBuilder.newInstance()
380	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
381	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
382	    }
