22	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
23	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
24	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
25	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
26	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
27	    @Mapping(target = "bulkSignupWarning", ignore = true)
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
32	     * (non-null and non-blank), otherwise {@code PHONE}.
33	     */
34	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
35	        if (owner == null) {
36	            return null;
37	        }
38	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
39	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
40	    }
41	
42	    /**
43	     * Derives an owner's locality (region) from the city using a fixed city-to-region table
44	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns
45	     * {@code "UNKNOWN"} when the city is not in the table.
46	     */
47	    default String formatLocality(Owner owner) {
48	        if (owner == null) {
49	            return null;
50	        }
51	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
52	            case "Sydney" -> "NSW";
53	            case "Melbourne" -> "VIC";
54	            case "Brisbane" -> "QLD";
55	            default -> "UNKNOWN";
56	        };
57	    }
58	
59	    /**
60	     * Computes an owner's membership level, a number from 1 to 3: starting at 1, plus 1 when an email
61	     * is present, plus 1 when the owner's namesake count is 0, capped at 3 (level 4 is reserved for
62	     * tenure).
63	     */
64	    default Integer formatMembershipLevel(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        int level = 1;
69	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
70	        if (hasEmail) {
71	            level++;
72	        }
73	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
74	        if (unique) {
75	            level++;
76	        }
77	        return Math.min(level, 3);
78	    }
79	
80	    /**
81	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
82	     * digits of the registration-date year (e.g. {@code "LON-SMI-0007-M26"}). Returns {@code null} when the
83	     * customer code or registration date is absent.
84	     */
85	    default String formatMembershipNumber(Owner owner) {
86	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
87	            return null;
88	        }
89	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
90	    }
91	
92	    /**
93	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
94	     */
95	    default String formatDisplayName(Owner owner) {
96	        if (owner == null) {
97	            return null;
